 public static Matrix4x4[] Matrices(SkinnedMeshRenderer r,Transform root)=>r.bones.Select((b,j)=>root.worldToLocalMatrix*b.localToWorldMatrix*r.sharedMesh.bindposes[j]).ToArray();
 public static Vector3[] Skin(SkinnedMeshRenderer r,Transform root){var mesh=r.sharedMesh;var p=mesh.vertices;var d=new Vector3[p.Length];for(int s=0;s<mesh.blendShapeCount;s++){float weight=r.GetBlendShapeWeight(s)*.01f;if(weight==0)continue;mesh.GetBlendShapeFrameVertices(s,0,d,null,null);for(int j=0;j<p.Length;j++)p[j]+=d[j]*weight;}var matrices=Matrices(r,root);var result=new Vector3[p.Length];using(var counts=mesh.GetBonesPerVertex())using(var weights=mesh.GetAllBoneWeights()){int at=0;for(int j=0;j<p.Length;j++)for(int k=0;k<counts[j];k++){var w=weights[at++];result[j]+=matrices[w.boneIndex].MultiplyPoint3x4(p[j])*w.weight;}}return result;}
 static string Hash(string path){using(var stream=File.OpenRead(path))using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","");}
 public static object Audit(){
 Guard();var root=PrefabUtility.LoadPrefabContents(Prefab);
 try{var face=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="Face");var outfit=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="Outfit");var sections=JObject.Parse(File.ReadAllText("Data/Liora/HierarchyRepair/sections.json"))["sections"];var body=sections.Single(s=>(string)s["name"]=="BAKED_body_lod0_mesh");int bodyEnd=(int)body["offset"]+(int)body["vertices"];
