 var report=new{prefab=Prefab,faceMesh=facePath,faceSha256=Hash(facePath),outfitMesh=outfitPath,outfitSha256=Hash(outfitPath),bodyVertices=V(skin),bodyTriangles=triangles,bodyCounts=cs.Select(x=>(int)x),bodyWeights=ws,bodyBonePaths=face.bones.Select(b=>AnimationUtility.CalculateTransformPath(b,root.transform)),bodyBoneNames=face.bones.Select(b=>b.name),faceNeutralMatrices=Matrices(face,root.transform).Select(M),clothVertices=V(cloth),clothTriangles=outfit.sharedMesh.triangles,clothRawVertices=V(outfit.sharedMesh.vertices),clothBonePaths=outfit.bones.Select(b=>AnimationUtility.CalculateTransformPath(b,root.transform)),clothBindPoses=outfit.sharedMesh.bindposes.Select(M),clothNeutralMatrices=Matrices(outfit,root.transform).Select(M),rendererQuality=outfit.quality.ToString(),outfitBounds=new{min=V(new[]{cloth.Aggregate(Vector3.Min)}),max=V(new[]{cloth.Aggregate(Vector3.Max)})},live=UnityEngine.Object.FindObjectsByType<SkinnedMeshRenderer>(FindObjectsInactive.Include).Where(r=>r.name=="Outfit"&&r.transform.root.name.Contains("Liora")&&r.gameObject.scene.IsValid()).Select(r=>new{root=r.transform.root.name,mesh=AssetDatabase.GetAssetPath(r.sharedMesh),active=r.gameObject.activeInHierarchy}),sections};File.WriteAllText(Data+"binding_input.json",JsonConvert.SerializeObject(report));}
 return new{faceVertices=skin.Length,outfitVertices=cloth.Length,outfitBoundsMin=cloth.Aggregate(Vector3.Min).ToString("F4"),outfitBoundsMax=cloth.Aggregate(Vector3.Max).ToString("F4"),faceProtected=true};
 }finally{PrefabUtility.UnloadPrefabContents(root);}
 }
 public static object Metadata(){Guard();var root=PrefabUtility.LoadPrefabContents(Prefab);try{var face=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="Face");var cloth=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="Outfit");var d=JObject.Parse(File.ReadAllText(Data+"binding_input.json"));using(var cs=cloth.sharedMesh.GetBonesPerVertex())using(var ws=cloth.sharedMesh.GetAllBoneWeights()){d["clothCounts"]=JArray.FromObject(cs.ToArray().Select(x=>(int)x));d["clothWeights"]=JArray.FromObject(ws.ToArray().Select(w=>new{bone=w.boneIndex,weight=w.weight}));}d["clothToFace"]=JArray.FromObject(M(face.transform.worldToLocalMatrix*cloth.transform.localToWorldMatrix));d["qualitySkinWeights"]=QualitySettings.skinWeights.ToString();d["faceQuality"]=face.quality.ToString();d["clothQuality"]=cloth.quality.ToString();d["faceInfluenceLimit"]=face.quality==SkinQuality.Auto?(int)QualitySettings.skinWeights:(int)face.quality;d["clothInfluenceLimit"]=cloth.quality==SkinQuality.Auto?(int)QualitySettings.skinWeights:(int)cloth.quality;File.WriteAllText(Data+"binding_input.json",d.ToString(Formatting.None));return new{QualitySettings.skinWeights,faceQuality=face.quality,clothQuality=cloth.quality};}finally{PrefabUtility.UnloadPrefabContents(root);}}
 static Matrix4x4 Weighted(byte count,Unity.Collections.NativeArray<BoneWeight1> ws,int at,Matrix4x4[] matrices){var result=Matrix4x4.zero;for(int j=0;j<count;j++){var w=ws[at+j];for(int k=0;k<16;k++)result[k]+=matrices[w.boneIndex][k]*w.weight;}return result;}
 public static object Build(){
 Guard();var root=PrefabUtility.LoadPrefabContents(Prefab);
 try{var face=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="Face");var outfit=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="Outfit");var source=outfit.sharedMesh;var data=JObject.Parse(File.ReadAllText(Data+"fitted_weights.json"));var rows=data["weights"];var mesh=UnityEngine.Object.Instantiate(source);mesh.name="Liora_Outfit_Fitted";mesh.ClearBlendShapes();var allBones=outfit.bones.Concat(face.bones).ToArray();var x=face.transform.worldToLocalMatrix*outfit.transform.localToWorldMatrix;var allBind=source.bindposes.Concat(face.sharedMesh.bindposes.Select(b=>b*x)).ToArray();var used=rows.SelectMany(row=>row.Select(p=>(int)p[0])).Distinct().OrderBy(i=>i).ToArray();var remap=used.Select((v,i)=>(v,i)).ToDictionary(p=>p.v,p=>p.i);var bones=used.Select(i=>allBones[i]).ToArray();mesh.bindposes=used.Select(i=>allBind[i]).ToArray();
 var counts=rows.Select(row=>(byte)row.Count()).ToArray();var weights=rows.SelectMany(row=>row.Select(p=>new BoneWeight1{boneIndex=remap[(int)p[0]],weight=(float)p[1]})).ToArray();using(var cs=new NativeArray<byte>(counts,Allocator.Temp))using(var ws=new NativeArray<BoneWeight1>(weights,Allocator.Temp))mesh.SetBoneWeights(cs,ws);
 var oldMatrices=Matrices(outfit,root.transform);var newMatrices=bones.Select((b,j)=>root.transform.worldToLocalMatrix*b.localToWorldMatrix*mesh.bindposes[j]).ToArray();var oldNormals=oldMatrices.Select(m=>m.inverse.transpose).ToArray();var newNormals=newMatrices.Select(m=>m.inverse.transpose).ToArray();var positionConversion=new Matrix4x4[source.vertexCount];var normalConversion=new Matrix4x4[source.vertexCount];
 using(var oldCounts=source.GetBonesPerVertex())using(var oldWeights=source.GetAllBoneWeights())using(var newCounts=mesh.GetBonesPerVertex())using(var newWeights=mesh.GetAllBoneWeights()){int oldAt=0,newAt=0;for(int j=0;j<source.vertexCount;j++){if((float)data["blend"][j]==0){positionConversion[j]=Matrix4x4.identity;normalConversion[j]=Matrix4x4.identity;}else{positionConversion[j]=Weighted(newCounts[j],newWeights,newAt,newMatrices).inverse*Weighted(oldCounts[j],oldWeights,oldAt,oldMatrices);normalConversion[j]=Weighted(newCounts[j],newWeights,newAt,newNormals).inverse*Weighted(oldCounts[j],oldWeights,oldAt,oldNormals);}oldAt+=oldCounts[j];newAt+=newCounts[j];}}
 var baseNormals=source.normals;var baseTangents=source.tangents;mesh.vertices=data["rawVertices"].Select(p=>new Vector3((float)p[0],(float)p[1],(float)p[2])).ToArray();mesh.normals=baseNormals.Select((v,j)=>normalConversion[j].MultiplyVector(v)).ToArray();mesh.tangents=baseTangents.Select((v,j)=>{var t=positionConversion[j].MultiplyVector(v);return new Vector4(t.x,t.y,t.z,v.w);}).ToArray();
 var dp=new Vector3[source.vertexCount];var dn=new Vector3[dp.Length];var dt=new Vector3[dp.Length];using(var w=new BinaryWriter(File.Create(Data+"outfit_desired_shapes.bin"))){w.Write(source.vertexCount);w.Write(source.blendShapeCount);for(int s=0;s<source.blendShapeCount;s++){source.GetBlendShapeFrameVertices(s,0,dp,dn,dt);for(int j=0;j<dp.Length;j++){dp[j]=positionConversion[j].MultiplyVector(dp[j]);dn[j]=normalConversion[j].MultiplyVector(dn[j]);dt[j]=positionConversion[j].MultiplyVector(dt[j]);Write(w,dp[j]);Write(w,dn[j]);Write(w,dt[j]);}var sentinel=Enumerable.Range(0,dp.Length).Select(j=>dp[j].sqrMagnitude>0||dn[j].sqrMagnitude>0||dt[j].sqrMagnitude>0?Vector3.right:Vector3.zero).ToArray();mesh.AddBlendShapeFrame(source.GetBlendShapeName(s),source.GetBlendShapeFrameWeight(s,0),dp,dn,sentinel);}}
 mesh.RecalculateBounds();var existing=AssetDatabase.LoadAssetAtPath<Mesh>(Candidate);if(existing){EditorUtility.CopySerialized(mesh,existing);UnityEngine.Object.DestroyImmediate(mesh);mesh=existing;EditorUtility.SetDirty(mesh);}else AssetDatabase.CreateAsset(mesh,Candidate);AssetDatabase.SaveAssets();var config=new{mesh=Candidate,source=AssetDatabase.GetAssetPath(source),bonePaths=bones.Select(b=>AnimationUtility.CalculateTransformPath(b,root.transform)),rootBone=AnimationUtility.CalculateTransformPath(outfit.rootBone,root.transform),vertices=mesh.vertexCount,triangles=mesh.triangles.Length/3,shapes=mesh.blendShapeCount};File.WriteAllText(Data+"candidate.json",JsonConvert.SerializeObject(config,Formatting.Indented));return new{draft=Candidate,mesh.vertexCount,shapes=mesh.blendShapeCount,boneSlots=bones.Length};
 }finally{PrefabUtility.UnloadPrefabContents(root);}
 }
 public static object Install(){
 Guard();var input=JObject.Parse(File.ReadAllText(Data+"binding_input.json"));if(Hash((string)input["faceMesh"])!=(string)input["faceSha256"])throw new Exception("Protected Face asset changed during fitting");var root=PrefabUtility.LoadPrefabContents(Prefab);
 try{var outfit=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="Outfit");var before=outfit.sharedMesh;var originalPath=AssetDatabase.GetAssetPath(before);var fitted=AssetDatabase.LoadAssetAtPath<Mesh>(Candidate);var config=JObject.Parse(File.ReadAllText(Data+"candidate.json"));var bones=config["bonePaths"].Select(p=>root.transform.Find((string)p)).ToArray();if(bones.Any(b=>!b))throw new Exception("Missing fitted bone");if(!before.triangles.SequenceEqual(fitted.triangles)||before.subMeshCount!=fitted.subMeshCount||before.blendShapeCount!=fitted.blendShapeCount||!before.colors32.SequenceEqual(fitted.colors32))throw new Exception("Garment topology or expression contract changed");
 for(int c=0;c<8;c++){var a=new List<Vector4>();var b=new List<Vector4>();before.GetUVs(c,a);fitted.GetUVs(c,b);if(!a.SequenceEqual(b))throw new Exception("Garment UV changed");}
 using(var r=new BinaryReader(File.OpenRead(Data+"outfit_desired_shapes.bin"))){int count=r.ReadInt32(),shapes=r.ReadInt32();var p=new Vector3[count];var n=new Vector3[count];var t=new Vector3[count];for(int s=0;s<shapes;s++){if(before.GetBlendShapeName(s)!=fitted.GetBlendShapeName(s)||before.GetBlendShapeFrameWeight(s,0)!=fitted.GetBlendShapeFrameWeight(s,0))throw new Exception("Shape definition changed");fitted.GetBlendShapeFrameVertices(s,0,p,n,t);for(int j=0;j<count;j++)foreach(var value in new[]{p[j],n[j],t[j]}){var expected=new Vector3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());if(!value.Equals(expected))throw new Exception("Fitted expression record changed");}}}
 float normalizationError=0;int maxInfluences=0;using(var cs=fitted.GetBonesPerVertex())using(var ws=fitted.GetAllBoneWeights()){int at=0;for(int j=0;j<fitted.vertexCount;j++){float total=0;maxInfluences=Math.Max(maxInfluences,cs[j]);for(int k=0;k<cs[j];k++){var w=ws[at++];if(w.boneIndex<0||w.boneIndex>=bones.Length||!float.IsFinite(w.weight)||w.weight<0)throw new Exception("Invalid weight");total+=w.weight;}normalizationError=Mathf.Max(normalizationError,Mathf.Abs(total-1));}}if(normalizationError>2e-6f)throw new Exception("Unnormalized weights");
 var oldBones=outfit.bones;var oldNeutral=Skin(outfit,root.transform);outfit.sharedMesh=fitted;outfit.bones=bones;var newNeutral=Skin(outfit,root.transform);var prescribed=JObject.Parse(File.ReadAllText(Data+"fitted_weights.json"))["clearanceWorldNeutral"];float maxNeutralError=0,maxDisplacement=0;for(int j=0;j<newNeutral.Length;j++){var expected=oldNeutral[j]+new Vector3((float)prescribed[j][0],(float)prescribed[j][1],(float)prescribed[j][2]);maxNeutralError=Mathf.Max(maxNeutralError,Vector3.Distance(newNeutral[j],expected));maxDisplacement=Mathf.Max(maxDisplacement,Vector3.Distance(newNeutral[j],oldNeutral[j]));}if(maxNeutralError>3e-6f)throw new Exception("Neutral compensation mismatch "+maxNeutralError);
 var bound=outfit.localBounds;var convert=outfit.transform.worldToLocalMatrix*root.transform.localToWorldMatrix;using(var file=new BinaryReader(File.OpenRead(Data+"predicted_fitted.bin")))while(file.BaseStream.Position<file.BaseStream.Length)bound.Encapsulate(convert.MultiplyPoint3x4(new Vector3(file.ReadSingle(),file.ReadSingle(),file.ReadSingle())));bound.Expand(new Vector3(.02f,.02f,.02f)/Mathf.Max(.00001f,outfit.transform.lossyScale.x));outfit.localBounds=bound;
 var errors=root.GetComponent<Character>().ValidateConfiguration();errors.AddRange(root.GetComponent<CharacterFlowController>().ValidateConfiguration());if(errors.Count>0)throw new Exception(string.Join(";",errors));PrefabUtility.SaveAsPrefabAsset(root,Prefab,out var success);if(!success)throw new Exception("Prefab save failed");AssetDatabase.SaveAssets();
 var live=new List<object>();foreach(var renderer in UnityEngine.Object.FindObjectsByType<SkinnedMeshRenderer>(FindObjectsInactive.Include).Where(r=>r.name=="Outfit"&&r.transform.root.name.Contains("Liora")&&r.gameObject.scene.IsValid()&&(AssetDatabase.GetAssetPath(r.sharedMesh)==originalPath||r.sharedMesh==fitted))){var owner=renderer.transform.root;var mapped=config["bonePaths"].Select(p=>owner.Find((string)p)).ToArray();if(mapped.Any(b=>!b))throw new Exception("Live garment skeleton missing");if(renderer.sharedMesh!=fitted||!renderer.bones.SequenceEqual(mapped)){Undo.RecordObject(renderer,"Fit Liora clothing");renderer.sharedMesh=fitted;renderer.bones=mapped;renderer.localBounds=bound;PrefabUtility.RecordPrefabInstancePropertyModifications(renderer);}live.Add(new{root=owner.name,mesh=AssetDatabase.GetAssetPath(renderer.sharedMesh),bones=renderer.bones.Length});}
 var report=new{installed=true,mesh=Candidate,live,boneSlots=bones.Length,maxInfluences,normalizationError,maxNeutralCompensationErrorM=maxNeutralError,maxAccumulatedNeutralDisplacementM=maxDisplacement,allShapeArraysMatchCompensatedSource=true,topologyUVMaterialsPreserved=true,faceSha256Unchanged=Hash((string)input["faceMesh"])==(string)input["faceSha256"],configurationErrors=errors,bodyMasking=false,sceneSaved=false,playModeTested=false};File.WriteAllText(Data+"installation.json",JsonConvert.SerializeObject(report,Formatting.Indented));return report;
 }finally{PrefabUtility.UnloadPrefabContents(root);}
 }
 public static object Samples(){
 Guard();var root=PrefabUtility.LoadPrefabContents(Prefab);
 try{var face=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="Face");var outfit=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="Outfit");var animator=root.GetComponentInChildren<Animator>(true);var rest=root.GetComponentsInChildren<Transform>(true).ToDictionary(t=>t,t=>(t.localPosition,t.localRotation,t.localScale));int bodyEnd=JObject.Parse(File.ReadAllText(Data+"binding_input.json"))["bodyVertices"].Count();var entries=new List<object>();
 Action reset=()=>{foreach(var p in rest){p.Key.localPosition=p.Value.Item1;p.Key.localRotation=p.Value.Item2;p.Key.localScale=p.Value.Item3;}for(int s=0;s<face.sharedMesh.blendShapeCount;s++)face.SetBlendShapeWeight(s,0);root.GetComponent<CharacterFacialMeshSync>()?.Apply();};
 using(var writer=new BinaryWriter(File.Create(Data+"samples.bin"))){writer.Write(bodyEnd);writer.Write(outfit.sharedMesh.vertexCount);writer.Write(face.bones.Length);writer.Write(outfit.bones.Length);
 Action<string,float,string> save=(name,phase,expression)=>{if(expression=="Joy")face.SetBlendShapeWeight(face.sharedMesh.GetBlendShapeIndex("emo_joy"),60);if(expression=="Speech"){face.SetBlendShapeWeight(face.sharedMesh.GetBlendShapeIndex("viseme_aa"),60);face.SetBlendShapeWeight(face.sharedMesh.GetBlendShapeIndex("emo_joy"),25);}root.GetComponent<CharacterFacialMeshSync>()?.Apply();foreach(var p in Skin(face,root.transform).Take(bodyEnd))Write(writer,p);foreach(var p in Skin(outfit,root.transform))Write(writer,p);foreach(var m in Matrices(face,root.transform))foreach(float v in M(m))writer.Write(v);foreach(var m in Matrices(outfit,root.transform))foreach(float v in M(m))writer.Write(v);entries.Add(new{name,phase,expression});};
 reset();save("Neutral",0,"Neutral");var definitions=AssetDatabase.FindAssets("t:AnimationDefinition",new[]{"Assets/_Sandbox/Data"}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<AnimationDefinition>).Where(d=>d&&d.Clip&&new[]{"Thinking","Talking","Waving","Idle","Confident Idle","Thumbs Up"}.Contains(d.name)).GroupBy(d=>d.Clip).Select(g=>g.First());
 foreach(var d in definitions){foreach(string expression in (d.name=="Thinking"||d.name=="Talking"||d.name=="Waving"?new[]{"Neutral",d.name=="Waving"?"Joy":"Speech"}:new[]{"Neutral"})){reset();var graph=PlayableGraph.Create("Liora garment fit sample");try{graph.SetTimeUpdateMode(DirectorUpdateMode.Manual);var p=AnimationClipPlayable.Create(graph,d.Clip);p.SetApplyFootIK(false);AnimationPlayableOutput.Create(graph,"pose",animator).SetSourcePlayable(p);graph.Play();int intervals=d.name=="Thinking"||d.name=="Talking"?12:8;for(int j=0;j<=intervals;j++){for(int s=0;s<face.sharedMesh.blendShapeCount;s++)face.SetBlendShapeWeight(s,0);p.SetTime(d.Clip.length*j/intervals);graph.Evaluate(0);save(d.name,(float)j/intervals,expression);}}finally{graph.Destroy();}}}
 }
 File.WriteAllText(Data+"samples.json",JsonConvert.SerializeObject(entries,Formatting.Indented));return new{poses=entries.Count,bodyVertices=bodyEnd};
 }finally{PrefabUtility.UnloadPrefabContents(root);}
 }
